function applyTheme(preference){themePreference=['light','dark','system','apollo'].includes(preference)?preference:'system';document.body.dataset.theme=themePreference==='apollo'||themePreference==='system'&&matchMedia('(prefers-color-scheme:dark)').matches?'dark':themePreference==='system'?'light':themePreference;document.body.dataset.palette=themePreference==='apollo'?'apollo':'';storage.set('theme',themePreference);const button=$('theme-button');if(button){button.innerHTML=icon(document.body.dataset.theme==='dark'?'sun':'moon');button.setAttribute('aria-label',`Switch to ${document.body.dataset.theme==='dark'?'light':'dark'} theme`);}if(state){renderScope();if(instrument!=='scope')renderAnalysisResult();}}
