function toast(message,error=false){const item=document.createElement('div');item.className='toast'+(error?' error':'');item.textContent=message;$('toasts').append(item);setTimeout(()=>item.remove(),error?8000:4300);}
function fmt(value,unit='',digits=3){if(value==null||!Number.isFinite(Number(value)))return '—';let n=Number(value),prefix='';const a=Math.abs(n);if(a>0&&a<1e-6){n*=1e9;prefix='n';}else if(a>0&&a<1e-3){n*=1e6;prefix='µ';}else if(a>0&&a<1){n*=1e3;prefix='m';}else if(a>=1e6){n/=1e6;prefix='M';}else if(a>=1000){n/=1000;prefix='k';}return `${Number(n.toPrecision(digits))} ${prefix}${unit}`.trim();}
function time(value){return fmt(value,'s',3);}
function selectedPart(){return scene?.parts.find(p=>p.id===state.selected);}
function componentReading(unit){const readings=state.measurement_inspection?.readings||[];return readings.find(r=>r.probe.id===`${unit==='A'?'i':'v'}:${state.selected}`)||readings.find(r=>r.probe.unit===unit);}
