function guards(){return {expected_command_revision:state.command_revision,expected_document_generation:state.document.generation};}
async function fetchJSON(url,options={}){const response=await fetch(url,{cache:'no-store',...options});if(response.status===304)return null;const data=await response.json();if(!response.ok||data.error&&typeof data.error==='string')throw new Error(typeof data.error==='string'?data.error:'The server refused this request.');return data;}
function command(name,params={},options={}){
 const run=async()=>{
  if(!state)throw new Error('The workbench is still connecting.');
  const request={version:1,id:crypto.randomUUID(),command:name,params};
  const capability=catalog?.commands.find(c=>c.id===name);
  if(capability?.mutation!==false)Object.assign(request,{key:crypto.randomUUID()},options.guard||guards());
  busy++;
  try{
   const reply=await fetchJSON('/api/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)});
   if(reply.error)throw new Error(reply.error.message||reply.help?.details||'The requested setting could not be applied.');
   await refresh(true);
   if(options.message)toast(options.message);
   return reply.result;
  }finally{busy--;}
 };
 const result=queue.then(run);queue=result.catch(()=>{});
 result.catch(error=>toast(error.message,true));return result;
}
async function refresh(force=false){const payload=await fetchJSON('/api/state'+(state&&!force?`?${new URLSearchParams({after:state.revision,instance:serverInstance||'',checkpoint:workspace.autosaved_at||'',storage_error:workspace.error||''})}`:''));if(payload){if(serverInstance&&payload.instance_id!==serverInstance){state=null;sceneKey='';inspectorKey='';fitted=false;}serverInstance=payload.instance_id;workspace=payload.workspace||{};if(!state||payload.state.revision>=state.revision){scene=payload.scene;applyState(payload.state);}}}

function applyState(next){if(state&&next.revision<state.revision)return;if(lastGeneration!=null&&next.document.generation!==lastGeneration){wireStart=null;placing=null;sceneKey='';fitted=false;mode='select';}lastGeneration=next.document.generation;state=next;render();}
async function poll(){try{await refresh();if(!online){online=true;toast('Reconnected to the local workbench.');}setConnection(true);}catch(error){if(online)toast('The local ELab server is unavailable. Restart it to reconnect.',true);online=false;setConnection(false);}setTimeout(poll,document.hidden?1500:180);}
function setConnection(ok){$('connection-dot').classList.toggle('offline',!ok);$('connection-status').textContent=ok?'Local engine connected':'Disconnected';}
function render(){if(!state)return;tools?.update();renderChrome();if(scene)renderScene();renderInspector();renderScope();if(instrument!=='scope')renderAnalysisResult();}
