function updateReadings(){const details=$('detailed-readings');if(details){const rows=selectedReadings(state,state.selected);const key=JSON.stringify(rows);if(details.dataset.key!==key){details.dataset.key=key;details.innerHTML=resultTable(rows);}}const target=$('component-readings');if(!target)return;const readings=(state.measurement_inspection?.readings||[]).filter(r=>['V','A','W','Ω','Hz'].includes(r.probe.unit));const chosen=[];for(const unit of ['V','A']){const found=componentReading(unit);if(found)chosen.push(found);}if(!chosen.length)chosen.push(...readings.slice(0,2));
 target.innerHTML=chosen.map(r=>`<div class="reading"><span>${esc(r.probe.unit==='V'?'Voltage':r.probe.unit==='A'?'Current':r.probe.label)}</span><strong>${esc(fmt(r.value,r.probe.unit,4))}</strong><small>${esc(r.state==='live'?'Accepted sample':r.reason||r.state)}</small></div>`).join('')||'<p class="muted">Connect the circuit to see accepted readings.</p>';
 if($('reading-note'))$('reading-note').textContent=state.measurement_inspection?.reason||(state.status==='error'?'Simulation stopped. Readings show the last accepted sample; restart to retry.':'Readings follow the same sample as the scope.');
}
