async function action(name){switch(name){case 'new':if(await confirmReplace('Start a new drawing?')){projectName='';await command('project.clear',{discard_changes:true});setTool('select');fit();}break;case 'examples':openExamples();break;case 'open':$('file-input').click();break;case 'save':await projects.save();break;case 'save-as':await projects.save(true);break;case 'download':await download('project');break;case 'projects':await projects.show();break;case 'tools':tools.show();break;case 'svg':await download('svg');break;case 'csv':await download('csv');break;case 'fit':fit();break;case 'sampling-fit':await command('simulation.sampling.fit',{}, {message:'Sampling fitted to circuit.'});break;case 'record':$('record-dialog').showModal();break;case 'help':$('help-dialog').showModal();break;case 'commands':showCommands();break;case 'theme':applyTheme(document.body.dataset.theme==='dark'?'light':'dark');break;case 'rotate':if(state.selected)await command('component.rotate',{id:state.selected});break;case 'delete':if(state.selected)await command('object.delete',{id:state.selected});break;case 'duplicate':if(state.selected){const p=selectedPart();if(p)await command('component.duplicate',{id:p.id,position:{x:p.position.x+100,y:p.position.y+80}});}break;case 'select-none':await command('component.select',{id:''});break;case 'switch':{const p=selectedPart();if(p)await command('switch.set',{id:p.id,closed:!p.switch_closed});break;}case 'button-hold':await command('button.set',{id:state.selected,pressed:true});break;case 'button-release':await command('button.set',{id:state.selected,pressed:false});break;case 'button':if(state.selected)await command('button.click',{id:state.selected});break;case 'live':await command('recording.view.set',{mode:'live'});break;}}
