 $('run-button').onclick=()=>command(state.paused?'simulation.resume':'simulation.pause');$('restart-button').onclick=()=>command('simulation.restart');$('step-button').onclick=()=>command('simulation.step',{duration_s:state.transient_settings.step_s});
 $('examples-button').onclick=openExamples;$('example-search').oninput=renderExamples;$('example-category').onchange=renderExamples;
