 $('command-button').onclick=showCommands;$('command-search').oninput=renderCommands;$('command-results').onclick=e=>{const quick=e.target.closest('[data-quick]');if(quick){$('command-dialog').close();action(quick.dataset.quick);return;}const chosen=e.target.closest('[data-command]');if(!chosen)return;currentCommand=catalog.commands.find(c=>c.id===chosen.dataset.command);$('command-editor').classList.remove('hidden');$('command-description').textContent=currentCommand.description;const schema=commandSchema(currentCommand,state,catalog.schemas);$('command-fields')._schema=schema;let initial={};if(state.selected)initial.id=state.selected;$('command-fields').innerHTML=schemaFields(schema,initial,catalog.schemas);$('command-params').value=JSON.stringify(initial,null,2);};
 $('command-execute').onclick=async()=>{if(!currentCommand)return;try{if(!$('raw-command-mode').checked&&!$('command-fields').reportValidity())return;const params=$('raw-command-mode').checked?JSON.parse($('command-params').value):readSchemaForm($('command-fields'),$('command-fields')._schema,catalog.schemas);const result=await command(currentCommand.id,params);if(currentCommand.mutation)$('command-dialog').close();else{$('command-result').textContent=JSON.stringify(result,null,2);$('command-description').textContent='Query result';}}catch(error){if(error instanceof SyntaxError)toast('Parameters must be valid JSON.',true);}};
 $('open-button').onclick=()=>action('open');$('save-button').onclick=()=>action('save');$('projects-button').onclick=()=>action('projects');$('tools-button').onclick=()=>action('tools');$('theme-button').onclick=()=>action('theme');$('help-button').onclick=()=>action('help');$('record-button').onclick=()=>action('record');$('csv-button').onclick=()=>action('csv');
 $('file-input').onchange=e=>{upload(e.target.files[0]);e.target.value='';};
